PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    date DATETIME DEFAULT CURRENT_TIMESTAMP,
    location TEXT
, game_code, current_slide_index);
CREATE TABLE sets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT
, category TEXT);
CREATE TABLE event_sets (
    event_id INTEGER REFERENCES events(id) ON DELETE CASCADE,
    set_id INTEGER REFERENCES sets(id) ON DELETE CASCADE,
    PRIMARY KEY (event_id, set_id)
);
CREATE TABLE teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER REFERENCES events(id) ON DELETE CASCADE,
    name TEXT NOT NULL
);
CREATE TABLE answers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    team_id INTEGER REFERENCES teams(id) ON DELETE CASCADE,
    question_id INTEGER REFERENCES questions(id) ON DELETE CASCADE,
    is_correct BOOLEAN DEFAULT 0,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
, answer_index INTEGER DEFAULT 0);
CREATE TABLE question_sets (
    question_id INTEGER REFERENCES questions(id) ON DELETE CASCADE,
    set_id INTEGER REFERENCES sets(id) ON DELETE CASCADE,
    PRIMARY KEY (question_id, set_id)
);
CREATE TABLE IF NOT EXISTS "questions" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                type TEXT CHECK(type IN ('multi_part', 'multiple_choice', 'matching', 'sequencing')),
                category TEXT,
                title TEXT,
                prompt TEXT NOT NULL,
                content JSON NOT NULL,
                media_url TEXT
            );
CREATE TABLE team_round_multipliers (
    team_id INTEGER REFERENCES teams(id) ON DELETE CASCADE,
    set_id INTEGER REFERENCES sets(id) ON DELETE CASCADE,
    multiplier REAL DEFAULT 1.0,
    PRIMARY KEY (team_id, set_id)
);
CREATE INDEX idx_teams_event_id ON teams(event_id);
CREATE INDEX idx_answers_team_id ON answers(team_id);
CREATE INDEX idx_answers_question_id ON answers(question_id);
CREATE INDEX idx_question_sets_set_id ON question_sets(set_id);
CREATE INDEX idx_questions_category ON questions(category);
COMMIT;
